import{_ as r,C as i,c as l,o as h,a3 as t,G as s,j as o,a as n}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Payment methods","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/payments-setup/payment-methods.md","filePath":"master/sales/point-of-sale/payments-setup/payment-methods.md","lastUpdated":1792041590000}'),m={name:"master/sales/point-of-sale/payments-setup/payment-methods.md"};function g(d,e,p,c,u,_){const a=i("ImagePopup");return h(),l("div",null,[e[3]||(e[3]=t('<h1 id="payment-methods" tabindex="-1">Payment methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment methods&quot;">​</a></h1><p>A payment method is a way for a customer to pay at the till, such as cash or a bank card. Each method is linked to an accounting journal, so every payment lands in the right account. You attach the methods to a register to offer them on the payment screen.</p><blockquote><p><strong>In simple words:</strong> A payment method is a button on the payment screen. Behind it sits a journal that records the money.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Point of Sale → Configurations → Payment Methods</code>.</p>',5)),s(a,{src:"/images1/pos/payment_methods_list.png",alt:"Payment Methods list with Cash for Spice Route Kitchen & Bar and TechNest Electronics"}),e[4]||(e[4]=t('<p>The list has the tabs <strong>All</strong>, <strong>Cash</strong> and <strong>Bank</strong>.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The method name, such as <strong>Cash</strong>.</li><li><strong><em>Type:</em></strong> <strong>Cash</strong>, <strong>Bank</strong> or <strong>Customer Account</strong>. Aureus sets it from the journal.</li><li><strong><em>Journal:</em></strong> The journal that records the payments, such as <strong>Cash Transactions</strong>.</li><li><strong><em>POS:</em></strong> The registers that use the method.</li><li><strong><em>Cash Drawer:</em></strong> <strong>Yes</strong> when the method counts as cash in the drawer.</li></ul><p>Use <strong>Group by</strong> for <strong>Type</strong> or <strong>Company</strong>.</p><h2 id="how-the-type-is-set" tabindex="-1">How the type is set <a class="header-anchor" href="#how-the-type-is-set" aria-label="Permalink to &quot;How the type is set&quot;">​</a></h2><p>You do not pick the type. Aureus reads it from the journal.</p><ul><li>A cash journal makes the method <strong>Cash</strong>. It is counted in the cash drawer.</li><li>A bank or credit card journal makes it <strong>Bank</strong>.</li><li>No journal makes it <strong>Customer Account</strong>. The sale stays on the customer receivable.</li></ul><h2 id="create-a-payment-method" tabindex="-1">Create a payment method <a class="header-anchor" href="#create-a-payment-method" aria-label="Permalink to &quot;Create a payment method&quot;">​</a></h2>',8)),o("ol",null,[e[1]||(e[1]=t("<li><p>Go to <code>Point of Sale → Configurations → Payment Methods</code>.</p></li><li><p>Click <strong>New Payment Method</strong>.</p></li><li><p>Fill in the <strong>General</strong> section.</p><ul><li><strong><em>Name:</em></strong> Required. For example <strong>Cash</strong>.</li><li><strong><em>Company:</em></strong> The company the method belongs to.</li><li><strong><em>Integration:</em></strong> Required. Choose <strong>None</strong>, <strong>Payment Terminal</strong> or <strong>QR Code</strong>. Use <strong>None</strong> for cash.</li><li><strong><em>Identify Customer:</em></strong> Switch it on to post one journal item per payment on the customer receivable.</li></ul></li>",3)),o("li",null,[e[0]||(e[0]=t("<p>Fill in the <strong>Accounting</strong> section.</p><ul><li><strong><em>Journal:</em></strong> Required. Pick the journal, for example <strong>Cash Transactions</strong>. Leave it empty only when <strong>Identify Customer</strong> is on.</li><li><strong><em>Intermediary Account:</em></strong> Leave it empty to use the default account from the company settings.</li></ul>",2)),s(a,{src:"/images1/pos/payment_method_form.png",alt:"Payment method form with Name Cash, Company My Company, Integration None and Journal Cash Transactions"})]),e[2]||(e[2]=o("li",null,[o("p",null,[n("Click "),o("strong",null,"Create"),n(".")])],-1))]),e[5]||(e[5]=t('<h2 id="attach-a-method-to-a-register" tabindex="-1">Attach a method to a register <a class="header-anchor" href="#attach-a-method-to-a-register" aria-label="Permalink to &quot;Attach a method to a register&quot;">​</a></h2><ol><li>Go to <code>Point of Sale → Configurations → Point of Sale</code> and open a register.</li><li>Open the <strong>Payment</strong> tab.</li><li>In <strong>Payment Methods</strong>, pick the methods. For example, pick <strong>Cash</strong> for <strong>TechNest Electronics</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol>',2)),s(a,{src:"/images1/pos/register_payment_tab.png",alt:"Register Payment tab with Payment Methods set to Cash"}),e[6]||(e[6]=t('<p>The field locks while a session is open. At the till, the payment screen lists the methods you picked. See <a href="./../selling/pay-and-receipt.html">Pay and receipt</a>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><ul><li><strong>Edit:</strong> Change a method.</li><li><strong>Delete:</strong> Archive the method. You can restore it later.</li><li><strong>Delete permanently:</strong> Possible only when the method has no payments.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot change or archive a method that a register uses while its session is open.</p></div><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>TechNest Electronics takes cash only. The method <strong>Cash</strong> uses the journal <strong>Cash Transactions</strong>. When Sofia Rossi pays 7,000 for order <strong>TNE/00001</strong>, the payment goes to that journal, and the change of 403 is booked as a negative line.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../orders-payments/payments.html">Payments</a></li><li><a href="./coins-and-bills.html">Coins and bills</a></li><li><a href="./../../../finance/configuration/">Finance configuration</a></li></ul>',8))])}const f=r(m,[["render",g]]);export{T as __pageData,f as default};
